 const mixedTimeSource=(await db.query("insert into time_entries(organization_id,external_id,customer_id,project_id,person_name,worker_type,work_date,hours,description,billable,approved,sales_rate) values($1,gen_random_uuid()::text,$2,$3,'Fixture','employee','2026-10-27',1,'Explicit additional work',true,true,0) returning id",[org,customer,mixedTimeProject.id])).rows[0].id;
 const mixedTimeInvoice=await create({sourceProject:mixedTimeProject.id,items:[line(100),line(80,'time',{timeEntryIds:[mixedTimeSource]})]});assert.equal(mixedTimeInvoice.status,201,JSON.stringify(mixedTimeInvoice.body));assert.equal(Number(mixedTimeInvoice.body.item.total),180);assert.equal((await transition(mixedTimeInvoice.body.item.number,'issue')).status,200,'Only explicitly agreed additional hours are added to the fixed component');
 assert.notEqual((await create({sourceProject:mixedTimeProject.id,items:[line(80,'time',{timeEntryIds:[mixedTimeSource]})]})).status,201,'Additional mixed-model time still cannot be billed twice');
