 for(const role of ['reader','member','project_manager']){await db.query('update organization_memberships set role=$1 where organization_id=$2 and user_id=$3',[role,org,current.userId]);assert.equal((await create(requestBody)).status,403);if(role==='project_manager'){const hidden=await originalTransaction(async c=>{await c.query("select set_config('app.organization_id',$1,true),set_config('app.user_id',$2,true)",[org,current.userId]);return c.query('select id from billing_agreements where id=$1',[milestoneAgreementId]);});assert.equal(hidden.rows.length,0,'Unassigned project managers cannot read the agreement directly');}}
