 const foreignCustomer=(await db.query("insert into customers(organization_id,external_id,customer_no,name) values($1,gen_random_uuid()::text,'V8-FOREIGN','Foreign fixture') returning id",[foreignOrganizationId])).rows[0].id;assert.equal((await create({...requestBody,customerId:foreignCustomer})).status,400);
